let data;

await new Promise((resolve, reject) =&gt; {
  Papa.parse("heatmap.csv", {
    download: true,
    header: true,
    dynamicTyping: true,
    complete: function(results) {
      data = results.data;
      resolve();
    },
    error: function(err) {
      console.error("Failed to load CSV", err);
      reject(err);
    }
  });
});

