&lt;header class="text-center mb-8"&gt;
    &lt;h1 class="text-4xl font-bold text-slate-800"&gt;OpenDengue Data Overview&lt;/h1&gt;
    &lt;p class="text-lg text-slate-600 mt-1"&gt;Visualise temporal and spatial data availability across regions and versions&lt;/p&gt;
&lt;/header&gt;

&lt;div class="controls-wrapper bg-white p-6 rounded-lg shadow-lg mb-8"&gt;
    &lt;div class="grid grid-cols-1 md:grid-cols-2 gap-6 items-center"&gt;
        &lt;div class="controls-container flex flex-col sm:flex-row sm:items-center sm:space-x-4 space-y-4 sm:space-y-0"&gt;
            &lt;div&gt;
                &lt;label for="regionSelect" class="block text-sm font-medium text-slate-700 mb-1"&gt;Region:&lt;/label&gt;
                &lt;select id="regionSelect" class="w-full sm:w-auto p-2 border border-slate-300 rounded-md shadow-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500"&gt;
                    &lt;option value="PAHO"&gt;PAHO&lt;/option&gt;
                    &lt;option value="WPRO"&gt;WPRO&lt;/option&gt;
                    &lt;option value="SEARO"&gt;SEARO&lt;/option&gt;
                    &lt;option value="EMRO"&gt;EMRO&lt;/option&gt;
                    &lt;option value="AFRO"&gt;AFRO&lt;/option&gt;
                    &lt;option value="EURO"&gt;EURO&lt;/option&gt;
                &lt;/select&gt;
            &lt;/div&gt;
            &lt;div&gt;
                &lt;label for="resolutionTypeSelect" class="block text-sm font-medium text-slate-700 mb-1"&gt;Heatmap Shows:&lt;/label&gt;
                &lt;select id="resolutionTypeSelect" class="w-full sm:w-auto p-2 border border-slate-300 rounded-md shadow-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500"&gt;
                    &lt;option value="Temporal"&gt;Temporal Resolution&lt;/option&gt;
                    &lt;option value="Spatial"&gt;Spatial Resolution&lt;/option&gt;
                &lt;/select&gt;
            &lt;/div&gt;
        &lt;/div&gt;

        &lt;div class="version-controls-container flex flex-col sm:flex-row sm:items-center sm:space-x-4 space-y-4 sm:space-y-0"&gt;
            &lt;div&gt;
                &lt;label for="currentVersionSelect" class="block text-sm font-medium text-slate-700 mb-1"&gt;Display Version:&lt;/label&gt;
                &lt;select id="currentVersionSelect" class="w-full sm:w-auto p-2 border border-slate-300 rounded-md shadow-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500"&gt;&lt;/select&gt;
            &lt;/div&gt;
            &lt;div class="flex items-center pt-5 sm:pt-0"&gt;
                &lt;input type="checkbox" id="enableComparison" class="h-5 w-5 text-blue-600 border-slate-300 rounded focus:ring-blue-500 mr-2"&gt;
                &lt;label for="enableComparison" class="text-sm font-medium text-slate-700"&gt;Enable Comparison&lt;/label&gt;
            &lt;/div&gt;
            &lt;div id="previousVersionControlSpan" class="previous-version-control" style="display: none;"&gt;
                 &lt;label for="previousVersionSelect" class="block text-sm font-medium text-slate-700 mb-1 sm:ml-2"&gt;Compare with:&lt;/label&gt;
                &lt;select id="previousVersionSelect" class="w-full sm:w-auto p-2 border border-slate-300 rounded-md shadow-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500"&gt;&lt;/select&gt;
            &lt;/div&gt;
        &lt;/div&gt;
    &lt;/div&gt;
&lt;/div&gt;

&lt;div class="main-content-area flex flex-col lg:flex-row gap-6"&gt;
    &lt;div id="heatmapDivContainer" class="flex-grow bg-white p-1 rounded-lg shadow-lg border border-slate-200"&gt;
         &lt;div id="heatmapDiv" style="width: 100%; height: 780px;"&gt;&lt;/div&gt;
    &lt;/div&gt;
    &lt;div id="summaryPanel" class="summary-panel lg:w-[320px] xl:w-[380px] flex-shrink-0 bg-white p-6 rounded-lg shadow-lg border border-slate-200" style="display: none; height: 780px; overflow-y: auto;"&gt;
        &lt;/div&gt;
&lt;/div&gt;

&lt;div id="messageBox" class="message-box mt-6 p-4 rounded-lg shadow-md" style="display: none;"&gt;
    &lt;/div&gt;

// Cell 1: Load Libraries and Define Global Constants Plotly = require(“plotly.js-dist@2.27.0/plotly.min.js”); Papa = require(“papaparse@5.3.2”);
TEMPORAL_LEVELS = ({ “Weekly”: 0, “Monthly”: 1, “Yearly”: 2, “NA”: 3 }); TEMPORAL_TEXT = ({ 0: “Weekly”, 1: “Monthly”, 2: “Yearly”, 3: “NA” }); TEMPORAL_COLORSCALE = [ [0.0, ‘#34D399’], [0.25, ‘#34D399’], [0.25, ‘#A7F3D0’], [0.5, ‘#A7F3D0’], [0.5, ‘#BAE6FD’], [0.75, ‘#BAE6FD’], [0.75, ‘#E5E7EB’], [1.0, ‘#E5E7EB’]]; SPATIAL_LEVELS = ({ “Admin2”: 0, “Admin1”: 1, “Admin0”: 2, “NA”: 3 }); SPATIAL_TEXT = ({ 0: “Admin2”, 1: “Admin1”, 2: “Admin0”, 3: “NA” }); SPATIAL_COLORSCALE = [ [0.0, ‘#EC4899’], [0.25, ‘#EC4899’], [0.25, ‘#F9A8D4’], [0.50, ‘#F9A8D4’], [0.50, ‘#FCE7F3’], [0.75, ‘#FCE7F3’], [0.75, ‘#E5E7EB’], [1.0, ‘#E5E7EB’]];
// Cell 2: Load Data from CSV // Make sure ‘heatmap.csv’ is in the same directory as this .qmd file. allData = { try { const data = await FileAttachment(“heatmap.csv”).csv({typed: true}); if (!data || data.length === 0) { console.warn(“heatmap.csv is empty or could not be parsed correctly.”); // Attempt to show message in UI const errorDiv = document.getElementById(‘messageBox’); if (errorDiv) { errorDiv.innerHTML = “Warning: ‘heatmap.csv’ is empty or could not be parsed. Some features may not work.”; errorDiv.className = ‘message-box mt-6 p-4 rounded-lg shadow-md bg-yellow-100 border border-yellow-400 text-yellow-700’; errorDiv.style.display = ‘block’; } return []; // Return empty array } return data; } catch (e) { console.error(“Error loading or parsing heatmap.csv:”, e); const errorDiv = document.getElementById(‘messageBox’); if (errorDiv) { errorDiv.innerHTML = Failed to load data: ${e.message}. Ensure 'heatmap.csv' is present and valid.; errorDiv.className = ‘message-box mt-6 p-4 rounded-lg shadow-md bg-red-100 border border-red-400 text-red-700’; errorDiv.style.display = ‘block’; } return []; // Return empty array to prevent downstream errors } }
// Cell 3: Define JavaScript Helper Functions window.Plotly = Plotly; let _sortedVersionsCache = [];
showMessage = (message, type = ‘info’, targetDivId = ‘messageBox’) =&gt; { const box = document.getElementById(targetDivId); if (!box) { console.error(“showMessage: Target div not found:”, targetDivId); return; } box.innerHTML = message;
let baseClasses = "";
let typeClasses = "";

if (targetDivId === 'summaryPanel') {
    baseClasses = 'summary-panel lg:w-[320px] xl:w-[380px] flex-shrink-0 bg-white p-6 rounded-lg shadow-lg border border-slate-200 text-slate-700';
    box.style.height = '780px';
    box.style.overflowY = 'auto';
} else {
    baseClasses = 'message-box mt-6 p-4 rounded-lg shadow-md';
    if (type === 'error') typeClasses = 'bg-red-100 border border-red-400 text-red-700';
    else if (type === 'info') typeClasses = 'bg-blue-100 border border-blue-400 text-blue-700';
    else typeClasses = 'bg-sky-100 border border-sky-400 text-sky-700';
}
box.className = `${baseClasses} ${typeClasses}`;
box.style.display = 'block';
}
hideMessage = (targetDivId = ‘messageBox’) =&gt; { const box = document.getElementById(targetDivId); if (box) { box.style.display = ‘none’; box.innerHTML = ’’; } }
sortVersions = (v1, v2) =&gt; { const parsePart = (part) =&gt; String(part).replace(‘V’, ’‘).split(’_’).map(Number); const parts1 = parsePart(v1); const parts2 = parsePart(v2); for (let i = 0; i &lt; Math.max(parts1.length, parts2.length); i++) { const p1 = parts1[i] || 0; const p2 = parts2[i] || 0; if (p1 !== p2) return p1 - p2; } return 0; }
populateVersionDropdowns = (dataForVersions, currentVersionSelectId, previousVersionSelectId) =&gt; { const currentDropdown = document.getElementById(currentVersionSelectId); const previousDropdown = document.getElementById(previousVersionSelectId); if (!currentDropdown || !previousDropdown) { console.error(“Version dropdown elements not found.”); _sortedVersionsCache = []; return; } currentDropdown.innerHTML = ’‘; previousDropdown.innerHTML =’’;
if (!dataForVersions || dataForVersions.length === 0) {
    currentDropdown.disabled = true;
    previousDropdown.disabled = true;
    _sortedVersionsCache = [];
    return;
}
_sortedVersionsCache = [...new Set(dataForVersions.map(d =&gt; String(d.version)))].sort(sortVersions);

_sortedVersionsCache.forEach(v =&gt; {
    currentDropdown.add(new Option(v, v));
    previousDropdown.add(new Option(v, v));
});

if (_sortedVersionsCache.length &gt; 0) {
    currentDropdown.value = _sortedVersionsCache[_sortedVersionsCache.length - 1];
    currentDropdown.disabled = false;
} else {
    currentDropdown.disabled = true;
    previousDropdown.disabled = true;
}
}
updatePreviousVersionSelection = () =&gt; { const currentVersionSelect = document.getElementById(‘currentVersionSelect’); const previousVersionSelect = document.getElementById(‘previousVersionSelect’); if (!currentVersionSelect || !previousVersionSelect) return;
const selectedCurrentVersion = currentVersionSelect.value;
const currentIndex = _sortedVersionsCache.indexOf(selectedCurrentVersion);

previousVersionSelect.disabled = _sortedVersionsCache.length &lt;= 1 || currentIndex === 0;

if (currentIndex &gt; 0) {
    previousVersionSelect.value = _sortedVersionsCache[currentIndex - 1];
} else if (_sortedVersionsCache.length &gt; 0 && _sortedVersionsCache.length &lt;=1 ) {
    previousVersionSelect.value = _sortedVersionsCache[0];
} else if (_sortedVersionsCache.length &gt; 1) {
     previousVersionSelect.value = _sortedVersionsCache[0];
}
}
updateHeatmap = (region, data, performComparison, selectedCurrentVersion, selectedPreviousVersion, selectedResolutionType) =&gt; { hideMessage(); hideMessage(‘summaryPanel’); const heatmapDiv = document.getElementById(‘heatmapDiv’); if (!heatmapDiv) { console.error(“heatmapDiv not found!”); return; } Plotly.purge(heatmapDiv);
const YEAR_MIN = 1990;
const YEAR_MAX = 2024;

if (!data || !Array.isArray(data) || data.length === 0) {
    showMessage('No data available to display heatmap. Ensure heatmap.csv is loaded.', 'error', 'messageBox');
    return;
}

const versionForHeatmap = selectedCurrentVersion;
if (!versionForHeatmap) {
    showMessage('Please select a version to display.', 'error', 'messageBox');
    return;
}

let currentVersionData = data.filter(d =&gt;
    String(d.version) === String(versionForHeatmap) &&
    d.region === region &&
    d.Year &gt;= YEAR_MIN && d.Year &lt;= YEAR_MAX
);

if (currentVersionData.length === 0) {
    const emptyMsg = `No data found for Region: '${region}', Version: ${versionForHeatmap} (Years: ${YEAR_MIN}-${YEAR_MAX}).`;
    showMessage(emptyMsg, 'info', 'messageBox');
    let summaryText = `&lt;h4 class="text-xl font-semibold mb-3 pb-2 border-b border-slate-300"&gt;Summary&lt;/h4&gt;&lt;ul&gt;&lt;li&gt;Displaying: ${versionForHeatmap}&lt;/li&gt;&lt;li&gt;Region: ${region}&lt;/li&gt;&lt;li&gt;Years: ${YEAR_MIN}-${YEAR_MAX}&lt;/li&gt;&lt;li&gt;Total Countries: 0&lt;/li&gt;&lt;li&gt;Total Tiles: 0&lt;/li&gt;&lt;/ul&gt;`;
    showMessage(summaryText, performComparison ? 'comparison_summary' : 'global_summary', 'summaryPanel');
    return;
}

const uniqueYears = [...new Set(currentVersionData.map(d =&gt; d.Year))].sort((a, b) =&gt; a - b);
const uniqueCountries = [...new Set(currentVersionData.map(d =&gt; d.adm_0_name))].sort();

if (uniqueCountries.length === 0 || uniqueYears.length === 0) {
    showMessage(`Not enough distinct data (countries or years) for ${region}, Version: ${versionForHeatmap}.`, 'info', 'messageBox');
    return;
}

const zValuesMatrix = uniqueCountries.map(() =&gt; uniqueYears.map(() =&gt; (selectedResolutionType === "Temporal" ? TEMPORAL_LEVELS["NA"] : SPATIAL_LEVELS["NA"])));
const hoverTextMatrix = uniqueCountries.map(() =&gt; uniqueYears.map(() =&gt; ''));

let counts = {};
const levelTexts = selectedResolutionType === "Temporal" ? TEMPORAL_TEXT : SPATIAL_TEXT;
Object.values(levelTexts).forEach(text =&gt; counts[text] = 0);
let totalDisplayedTiles = 0;

currentVersionData.forEach(d =&gt; {
    const yearIndex = uniqueYears.indexOf(d.Year);
    const countryIndex = uniqueCountries.indexOf(d.adm_0_name);
    if (yearIndex !== -1 && countryIndex !== -1) {
        totalDisplayedTiles++;
        let resValue;
        const currentTResText = d.T_res_nm || "NA";
        const currentSResText = d.S_res_nm || "NA";

        if (selectedResolutionType === "Temporal") {
            resValue = TEMPORAL_LEVELS[currentTResText] !== undefined ? TEMPORAL_LEVELS[currentTResText] : TEMPORAL_LEVELS["NA"];
            counts[currentTResText] = (counts[currentTResText] || 0) + 1;
        } else {
            resValue = SPATIAL_LEVELS[currentSResText] !== undefined ? SPATIAL_LEVELS[currentSResText] : SPATIAL_LEVELS["NA"];
            counts[currentSResText] = (counts[currentSResText] || 0) + 1;
        }
        zValuesMatrix[countryIndex][yearIndex] = resValue;
        hoverTextMatrix[countryIndex][yearIndex] = `&lt;b&gt;Country:&lt;/b&gt; ${uniqueCountries[countryIndex]}&lt;br&gt;&lt;b&gt;Year:&lt;/b&gt; ${uniqueYears[yearIndex]}&lt;br&gt;&lt;b&gt;T.Res:&lt;/b&gt; ${currentTResText}&lt;br&gt;&lt;b&gt;S.Res:&lt;/b&gt; ${currentSResText}`;
    }
});

const plotDataConfig = [{
    x: uniqueYears, y: uniqueCountries, z: zValuesMatrix, type: 'heatmap',
    text: hoverTextMatrix,
    hovertemplate: '%{text}&lt;extra&gt;&lt;/extra&gt;',
    zmin: 0,
    zmax: selectedResolutionType === "Temporal" ? Object.keys(TEMPORAL_LEVELS).length - 1 : Object.keys(SPATIAL_LEVELS).length - 1,
    colorscale: selectedResolutionType === "Temporal" ? TEMPORAL_COLORSCALE : SPATIAL_COLORSCALE,
    showscale: true,
    colorbar: {
        tickvals: Object.values(selectedResolutionType === "Temporal" ? TEMPORAL_LEVELS : SPATIAL_LEVELS),
        ticktext: Object.keys(selectedResolutionType === "Temporal" ? TEMPORAL_LEVELS : SPATIAL_LEVELS),
        len: 0.7, y: 0.5, yanchor: 'middle', thickness: 15,
        tickfont: { family: 'Inter, sans-serif', size: 10, color: '#334155'},
        title: { text: selectedResolutionType === "Temporal" ? 'Temporal Res.' : 'Spatial Res.', font: { family: 'Inter, sans-serif', size: 12, color: '#334155'}, side: 'right'}
    },
    xgap: 1, ygap: 1
}];

const summaryPanelDiv = document.getElementById('summaryPanel');
if (summaryPanelDiv) summaryPanelDiv.style.display = 'block';

if (performComparison && selectedCurrentVersion && selectedPreviousVersion && selectedCurrentVersion !== selectedPreviousVersion) {
    let comparisonSummaryText = `&lt;h4 class="text-xl font-semibold text-slate-800 mb-4 pb-2 border-b border-slate-300"&gt;Comparison Summary&lt;/h4&gt;&lt;ul class="space-y-1 text-sm text-slate-700"&gt;`;
    comparisonSummaryText += `&lt;li&gt;&lt;strong&gt;Displaying:&lt;/strong&gt; ${selectedCurrentVersion}&lt;/li&gt;`;
    comparisonSummaryText += `&lt;li&gt;&lt;strong&gt;Comparing with:&lt;/strong&gt; ${selectedPreviousVersion}&lt;/li&gt;`;

    const prevVersionDataFull = data.filter(d =&gt; String(d.version) === String(selectedPreviousVersion) && d.Year &gt;= YEAR_MIN && d.Year &lt;= YEAR_MAX);
    const prevCountriesAll = new Set(prevVersionDataFull.map(d =&gt; d.adm_0_name));
    const newCountriesList = uniqueCountries.filter(c =&gt; !prevCountriesAll.has(c));

    const prevVersionDataRegion = prevVersionDataFull.filter(d =&gt; d.region === region);
    const prevDataMap = new Map();
    prevVersionDataRegion.forEach(d_prev =&gt; {
        prevDataMap.set(`${d_prev.adm_0_name}_${d_prev.Year}`, {
            t_level: TEMPORAL_LEVELS[d_prev.T_res_nm || "NA"],
            s_level: SPATIAL_LEVELS[d_prev.S_res_nm || "NA"],
        });
    });

    let newMeaningfulForSelectedTypeCount = 0;
    let improvedForSelectedTypeCount = 0;

    const zNewHighlight = uniqueCountries.map(() =&gt; uniqueYears.map(() =&gt; null));
    const zImprovedHighlight = uniqueCountries.map(() =&gt; uniqueYears.map(() =&gt; null));

    currentVersionData.forEach(d_curr =&gt; {
        const tileKey = `${d_curr.adm_0_name}_${d_curr.Year}`;
        const prevEntry = prevDataMap.get(tileKey);
        const curr_t_level = TEMPORAL_LEVELS[d_curr.T_res_nm || "NA"];
        const curr_s_level = SPATIAL_LEVELS[d_curr.S_res_nm || "NA"];
        const countryIndex = uniqueCountries.indexOf(d_curr.adm_0_name);
        const yearIndex = uniqueYears.indexOf(d_curr.Year);
        let classifiedAsNewMeaningfulPrimary = false;
        let classifiedAsImprovedPrimary = false;
        const currentPrimaryLevel = (selectedResolutionType === "Temporal") ? curr_t_level : curr_s_level;
        const NA_LEVEL_FOR_PRIMARY = (selectedResolutionType === "Temporal") ? TEMPORAL_LEVELS["NA"] : SPATIAL_LEVELS["NA"];
        const currentPrimaryIsNA = currentPrimaryLevel === NA_LEVEL_FOR_PRIMARY;
        const previousPrimaryLevel = prevEntry ?
                                  ((selectedResolutionType === "Temporal") ? prevEntry.t_level : prevEntry.s_level)
                                  : undefined;

        if (!currentPrimaryIsNA && (!prevEntry || previousPrimaryLevel === NA_LEVEL_FOR_PRIMARY)) {
            newMeaningfulForSelectedTypeCount++;
            classifiedAsNewMeaningfulPrimary = true;
        } else if (prevEntry && !currentPrimaryIsNA &&
                   previousPrimaryLevel !== NA_LEVEL_FOR_PRIMARY &&
                   currentPrimaryLevel &lt; previousPrimaryLevel) {
            improvedForSelectedTypeCount++;
            classifiedAsImprovedPrimary = true;
        }

        if (countryIndex !== -1 && yearIndex !== -1) {
            let hoverPrefix = "";
            if (classifiedAsNewMeaningfulPrimary) {
                zNewHighlight[countryIndex][yearIndex] = 4;
                hoverPrefix = `&lt;span style="color:#DC2626; font-weight:bold;"&gt;New Meaningful ${selectedResolutionType === "Temporal" ? "T.Res" : "S.Res"}&lt;/span&gt;&lt;br&gt;`;
            } else if (classifiedAsImprovedPrimary) {
                zImprovedHighlight[countryIndex][yearIndex] = 5;
                hoverPrefix = `&lt;span style="color:#2563EB; font-weight:bold;"&gt;Improved ${selectedResolutionType === "Temporal" ? "T.Res" : "S.Res"}&lt;/span&gt;&lt;br&gt;`;
            }
            if (hoverPrefix) {
                plotDataConfig[0].text[countryIndex][yearIndex] = hoverPrefix + plotDataConfig[0].text[countryIndex][yearIndex];
            }
        }
    });

    comparisonSummaryText += `&lt;li&gt;New countries in region: &lt;span class="summary-new-country"&gt;${newCountriesList.length}&lt;/span&gt; ${newCountriesList.length &gt; 0 ? `(${newCountriesList.join(', ')})` : ''}&lt;/li&gt;`;
    comparisonSummaryText += `&lt;li&gt;New meaningful tiles (for ${selectedResolutionType}): &lt;span class="summary-new-tile"&gt;${newMeaningfulForSelectedTypeCount}&lt;/span&gt;&lt;/li&gt;`;
