function sortVersions(v1, v2) {
    const parsePart = (part) =&gt; String(part).replace('V', '').split('_').map(Number);
    const parts1 = parsePart(v1);
    const parts2 = parsePart(v2);
    for (let i = 0; i &lt; Math.max(parts1.length, parts2.length); i++) {
        const p1 = parts1[i] || 0;
        const p2 = parts2[i] || 0;
        if (p1 !== p2) return p1 - p2;
    }
    return 0;
}

