    } else {
        let globalSummaryText = `&lt;h4 class="text-xl font-semibold text-slate-800 mb-4 pb-2 border-b border-slate-300"&gt;Global Summary&lt;/h4&gt;&lt;ul class="space-y-1 text-sm text-slate-700"&gt;`;
        globalSummaryText += `&lt;li&gt;&lt;strong&gt;Displaying Version:&lt;/strong&gt; ${versionForHeatmap}&lt;/li&gt;`;
        globalSummaryText += `&lt;li&gt;&lt;strong&gt;Region:&lt;/strong&gt; ${region}&lt;/li&gt;`;
        globalSummaryText += `&lt;li&gt;&lt;strong&gt;Years:&lt;/strong&gt; ${uniqueYears.length &gt; 0 ? uniqueYears[0] + ' - ' + uniqueYears[uniqueYears.length -1] : 'N/A'} &lt;/li&gt;`;
        globalSummaryText += `&lt;li&gt;&lt;strong&gt;Total Countries in Selection:&lt;/strong&gt; ${uniqueCountries.length}&lt;/li&gt;`;
        globalSummaryText += `&lt;li&gt;&lt;strong&gt;Total Tiles Displayed:&lt;/strong&gt; ${totalDisplayedTiles}&lt;/li&gt;`;
        Object.keys(levelTexts).forEach(levelKey =&gt; {
            const text = levelTexts[levelKey];
            const countVal = counts[text] || 0;
            const percentage = totalDisplayedTiles &gt; 0 ? ((countVal / totalDisplayedTiles) * 100).toFixed(1) : "0.0";
            globalSummaryText += `&lt;li&gt;${text} Tiles: ${countVal} (${percentage}%)&lt;/li&gt;`;
        });
        globalSummaryText += `&lt;/ul&gt;`;
        showMessage(globalSummaryText, 'global_summary', 'summaryPanel');
    }

    let titleSuffix = selectedResolutionType === "Temporal" ? "Temporal Resolution" : "Spatial Resolution";
    const layout = {
        title: { text: `Best ${titleSuffix} Available - ${region} (${versionForHeatmap})`, x: 0.5, xanchor: 'center', font: { family: 'Inter, sans-serif', size: 18, color: '#1e293b'}},
        autosize: true, height: 780,
        xaxis: { title: {text: 'Year', font: {family: 'Inter, sans-serif', size: 13, color: '#334155'}}, dtick: uniqueYears.length &gt; 20 ? Math.ceil(uniqueYears.length / 15) : 1, tickangle: uniqueYears.length &gt; 25 ? 45 : 0, tickfont: { family: 'Inter, sans-serif', size: 11, color: '#475569'}, gridcolor: '#e2e8f0', automargin: true },
