function updatePlot(region = "PAHO", resolutionType = "Temporal") {
  const filtered = data.filter(d =&gt; d.region === region && d.Year &gt;= 1990 && d.Year &lt;= 2024);
  const years = [...new Set(filtered.map(d =&gt; d.Year))].sort((a, b) =&gt; a - b);
  const countries = [...new Set(filtered.map(d =&gt; d.adm_0_name))].sort();

  const levelMap = resolutionType === "Temporal"
    ? { "Weekly": 0, "Monthly": 1, "Yearly": 2, "NA": 3 }
    : { "Admin2": 0, "Admin1": 1, "Admin0": 2, "NA": 3 };

  const z = countries.map(() =&gt; years.map(() =&gt; levelMap["NA"]));
  const text = countries.map(() =&gt; years.map(() =&gt; ""));

  filtered.forEach(d =&gt; {
    const i = countries.indexOf(d.adm_0_name);
    const j = years.indexOf(d.Year);
    const key = resolutionType === "Temporal" ? d.T_res_nm : d.S_res_nm;
    if (i !== -1 && j !== -1) {
      z[i][j] = levelMap[key] ?? levelMap["NA"];
      text[i][j] = \`Country: \${d.adm_0_name}&lt;br&gt;Year: \${d.Year}&lt;br&gt;T.Res: \${d.T_res_nm}&lt;br&gt;S.Res: \${d.S_res_nm}\`;
    }
  });

  Plotly.newPlot("plot", [{
    x: years,
    y: countries,
    z,
    text,
    type: "heatmap",
    hoverinfo: "text",
    colorscale: resolutionType === "Temporal"
      ? [[0, '#34D399'], [0.25, '#A7F3D0'], [0.5, '#BAE6FD'], [0.75, '#E5E7EB'], [1, '#E5E7EB']]
      : [[0, '#EC4899'], [0.25, '#F9A8D4'], [0.5, '#FCE7F3'], [0.75, '#E5E7EB'], [1, '#E5E7EB']]
  }], {
    title: \`Best \${resolutionType} Resolution – \${region}\`,
    height: 780,
    margin: { t: 60, b: 80, l: 120, r: 20 },
    xaxis: { title: "Year" },
    yaxis: { title: "Country" },
    font: { family: 'Inter, sans-serif', size: 12 }
  });
}

updatePlot();
document.getElementById("regionSelect").addEventListener("change", () =&gt; {
  updatePlot(
    document.getElementById("regionSelect").value,
    document.getElementById("resolutionSelect").value
  );
});

document.getElementById("resolutionSelect").addEventListener("change", () =&gt; {
  updatePlot(
    document.getElementById("regionSelect").value,
    document.getElementById("resolutionSelect").value
  );
});

